// @module IronOn
define('IronOn.Item.Model', [
    'Backbone',
    'underscore',
    'Utils'
], function IronOnItemModel(
    Backbone,
    _,
    Utils
) {
    'use strict';

    return Backbone.Model.extend({

        // @method initialize
        // @return {Void}
        initialize: function initialize(options) {
            // Wires the config options to the URL of the model
            // todo use own fieldset
            this.searchApiMasterOptions = options.container.getComponent('Environment').getConfig('searchApiMasterOptions.itemDetails');
            this.searchApiMasterOptions.fieldset = 'ironon';
        },

        url: function url() {
            var urlRoot = Utils.addParamsToUrl(
                '/api/items',
                this.searchApiMasterOptions
            );

            return urlRoot;
        }
    });
});

define('IronOn.ItemPrice', [
    'ironon_item_price.tpl',
    'Backbone',
    'underscore',
    'Utils'
], function IronOnPatchesAndPinsView(
    irononItemPriceTpl,
    Backbone,
    _
) {
    'use strict';

    return Backbone.View.extend({

        template: irononItemPriceTpl,

        getContext: function getContext() {
            var pdp = this.options.container.getComponent('PDP');
            var itemInfo = pdp.getItemInfo();
            var selectedChild = pdp.getSelectedMatrixChilds();
            var itemPrice;
            var itemPriceWIronOn;
            if (selectedChild && selectedChild.length === 1) {
                itemPrice = selectedChild[0].onlinecustomerprice_detail.onlinecustomerprice
            } else {
                itemPrice = itemInfo.item.onlinecustomerprice
            }
            itemPriceWIronOn = parseFloat(this.options.parent.ironOnPrice, 10) ? itemPrice + parseFloat(this.options.parent.ironOnPrice, 10) : itemPrice;
            return {
                itemPrice: _.formatCurrency(itemPriceWIronOn)
            };
        }
    });
});

define('IronOn', [
    'IronOn.View',
    'IronOn.Cart.HideActions',
    'IronOn.Cart.AddToCart.Button.View',
    'IronOn.ProductViews.Price.View',
    'IronOn.CartConfirmation.View'
], function IronOn(
    IronOnView,
    IronOnCartHideActions
) {
    'use strict';

    function hideWishlistForIronOn(pdp, ironOnConfiguration) {
        pdp.addToViewContextDefinition('ProductDetails.Full.View', 'isIronOnItem', 'boolean', function addToViewContextDefinition(context) {
            var isIronOnItem = false;
            try {
                isIronOnItem = context.model.item[ironOnConfiguration.troopNumeralField] || context.model.item.custitem_acs_enable_monogram;
            } catch (e) {
                // eslint-disable-next-line no-console
                console.log(e);
            }
            return isIronOnItem;
        });
    }

    return {
        mountToApp: function mountToApp(container) {
            var pdp = container.getComponent('PDP');
            var environment = container.getComponent('Environment');
            var ironOnConfiguration = environment.getConfig('extensions').ironon;
            if (pdp && ironOnConfiguration) {
                pdp.addChildView('Product.Options', function addChildView() {
                    return new IronOnView({
                        container: container
                    });
                });
                pdp.addChildViews(pdp.PDP_QUICK_VIEW, {
                    'Product.Options': {
                        'IronOnView': {
                            childViewIndex: 10,
                            childViewConstructor: function childViewConstructor() {
                                return new IronOnView({
                                    container: container
                                });
                            }
                        }
                    }
                });
                hideWishlistForIronOn(pdp, ironOnConfiguration);
                IronOnCartHideActions.hideCartActions(container);
            }
        }
    };
});

define('IronOn.MyAccount', [
    'IronOn.Cart.HideActions',
    'IronOn.Cart.AddToCart.Button.View',
    'IronOn.ProductViews.Price.View',
    'IronOn.CartConfirmation.View'
